export type ContextPressureRecoveryStatus =
  | "recovered"
  | "unknown"
  | "depth-exceeded";

export type ContextPressureRecoverySectionName =
  | "goal"
  | "unfinishedWork"
  | "dependencies"
  | "recentEvidence";

export interface ContextPressureRecoverySection {
  items: string[];
  keptCount: number;
  droppedCount: number;
  totalCount: number;
  truncated: boolean;
}

export interface ContextPressureRecoverySections {
  goal: ContextPressureRecoverySection;
  unfinishedWork: ContextPressureRecoverySection;
  dependencies: ContextPressureRecoverySection;
  recentEvidence: ContextPressureRecoverySection;
}

export interface ContextPressureRecoveryDroppedCounts {
  goal: number;
  unfinishedWork: number;
  dependencies: number;
  recentEvidence: number;
  total: number;
}

export interface ContextPressureRecoveryResult {
  status: ContextPressureRecoveryStatus;
  recovered: boolean;
  complete: false;
  digest: string;
  sections?: ContextPressureRecoverySections;
  truncated: boolean;
  keptCount: number;
  droppedCount: number;
  totalCount: number;
  dropped: ContextPressureRecoveryDroppedCounts;
}

export interface ContextPressureRecoveryOptions {
  /** Maximum number of items retained independently in each section. */
  maxItemsPerSection?: number;
  /** Maximum working-context/handoff chain depth accepted by the projection. */
  maxDepth?: number;
}

export interface WorkingContextRecoverySnapshot {
  goal?: unknown;
  goals?: unknown;
  unfinishedWork?: unknown;
  openWork?: unknown;
  openTasks?: unknown;
  nextActions?: unknown;
  dependencies?: unknown;
  recentEvidence?: unknown;
  depth?: number;
  workingContext?: WorkingContextRecoverySnapshot;
  [key: string]: unknown;
}

const SECTION_NAMES: readonly ContextPressureRecoverySectionName[] = [
  "goal",
  "unfinishedWork",
  "dependencies",
  "recentEvidence",
];

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function firstDefined(
  record: Record<string, unknown>,
  names: readonly string[],
): unknown {
  for (const name of names) {
    if (Object.prototype.hasOwnProperty.call(record, name)) {
      return record[name];
    }
  }
  return undefined;
}

function normalizeItem(value: unknown): string | undefined {
  if (typeof value === "string") {
    const normalized = value.trim();
    return normalized.length > 0 ? normalized : undefined;
  }
  if (typeof value === "number" || typeof value === "boolean") {
    return String(value);
  }
  if (isRecord(value)) {
    const stable = stableStringify(value);
    return stable.length > 0 ? stable : undefined;
  }
  return undefined;
}

function toItems(value: unknown): string[] {
  if (value === undefined || value === null) {
    return [];
  }
  const values = Array.isArray(value) ? value : [value];
  const items: string[] = [];
  for (const item of values) {
    const normalized = normalizeItem(item);
    if (normalized !== undefined) {
      items.push(normalized);
    }
  }
  return items;
}

function stableStringify(value: unknown): string {
  if (value === null) {
    return "null";
  }
  if (Array.isArray(value)) {
    return `[${value.map(stableStringify).join(",")}]`;
  }
  if (isRecord(value)) {
    const entries = Object.keys(value)
      .sort()
      .map((key) => `${JSON.stringify(key)}:${stableStringify(value[key])}`);
    return `{${entries.join(",")}}`;
  }
  if (typeof value === "undefined") {
    return "null";
  }
  return JSON.stringify(value);
}

function fnv1a64(input: string, seed: bigint): string {
  const prime = 0x100000001b3n;
  const mask = 0xffffffffffffffffn;
  let hash = seed;
  for (const character of input) {
    const code = character.codePointAt(0) ?? 0;
    hash ^= BigInt(code & 0xff);
    hash = BigInt.asUintN(64, hash * prime);
    hash ^= BigInt((code >>> 8) & 0xff);
    hash = BigInt.asUintN(64, hash * prime);
  }
  return hash.toString(16).padStart(16, "0");
}

/** A deterministic, non-cryptographic digest suitable for cache and replay comparisons. */
export function contextPressureRecoveryDigest(value: unknown): string {
  const input = stableStringify(value);
  return `${fnv1a64(input, 0xcbf29ce484222325n)}${fnv1a64(
    `context-pressure-recovery:${input}`,
    0x84222325cbf29ce4n,
  )}`;
}

function emptySection(): ContextPressureRecoverySection {
  return {
    items: [],
    keptCount: 0,
    droppedCount: 0,
    totalCount: 0,
    truncated: false,
  };
}

function emptyDropped(): ContextPressureRecoveryDroppedCounts {
  return {
    goal: 0,
    unfinishedWork: 0,
    dependencies: 0,
    recentEvidence: 0,
    total: 0,
  };
}

function extractSnapshot(input: unknown): Record<string, unknown> {
  if (!isRecord(input)) {
    return {};
  }
  const nested = input.workingContext;
  if (!isRecord(nested)) {
    return input;
  }
  return { ...nested, ...input, workingContext: nested };
}

function sectionValues(
  snapshot: Record<string, unknown>,
): Record<ContextPressureRecoverySectionName, string[]> {
  const goal = firstDefined(snapshot, ["goal", "goals"]);
  const unfinishedWork = firstDefined(snapshot, [
    "unfinishedWork",
    "openWork",
    "openTasks",
    "nextActions",
  ]);
  const dependencies = firstDefined(snapshot, ["dependencies"]);
  const recentEvidence = firstDefined(snapshot, ["recentEvidence"]);

  return {
    goal: toItems(goal),
    unfinishedWork: toItems(unfinishedWork),
    dependencies: toItems(dependencies),
    recentEvidence: toItems(recentEvidence),
  };
}

function normalizeLimit(value: number | undefined, fallback: number): number {
  if (value === undefined || !Number.isFinite(value)) {
    return fallback;
  }
  return Math.max(0, Math.floor(value));
}

/**
 * Projects a bounded recovery summary from an existing Working Context snapshot.
 *
 * The operation is fail-closed for excessive depth, never mutates its input,
 * accounts for every source item, and never reports task completion.
 */
export function recoverContextPressureRecovery(
  snapshot: unknown,
  options: ContextPressureRecoveryOptions = {},
): ContextPressureRecoveryResult {
  const source = extractSnapshot(snapshot);
  const maxDepth = normalizeLimit(options.maxDepth, 20);
  const rawDepth = source.depth;
  const depth =
    typeof rawDepth === "number" && Number.isFinite(rawDepth)
      ? Math.max(0, Math.floor(rawDepth))
      : 0;

  if (depth > maxDepth) {
    const digest = contextPressureRecoveryDigest({
      status: "depth-exceeded",
      depth,
      maxDepth,
    });
    return {
      status: "depth-exceeded",
      recovered: false,
      complete: false,
      digest,
      truncated: false,
      keptCount: 0,
      droppedCount: 0,
      totalCount: 0,
      dropped: emptyDropped(),
    };
  }

  const values = sectionValues(source);
  const totalCount = SECTION_NAMES.reduce(
    (count, name) => count + values[name].length,
    0,
  );

  if (totalCount === 0) {
    return {
      status: "unknown",
      recovered: false,
      complete: false,
      digest: contextPressureRecoveryDigest({
        status: "unknown",
        depth,
        maxDepth,
      }),
      truncated: false,
      keptCount: 0,
      droppedCount: 0,
      totalCount: 0,
      dropped: emptyDropped(),
    };
  }

  const maxItemsPerSection = normalizeLimit(options.maxItemsPerSection, 20);
  const sections: ContextPressureRecoverySections = {
    goal: emptySection(),
    unfinishedWork: emptySection(),
    dependencies: emptySection(),
    recentEvidence: emptySection(),
  };
  const dropped = emptyDropped();
  let keptCount = 0;
  let droppedCount = 0;

  for (const name of SECTION_NAMES) {
    const items = values[name];
    const kept = items.slice(0, maxItemsPerSection);
    const droppedForSection = items.length - kept.length;
    sections[name] = {
      items: kept,
      keptCount: kept.length,
      droppedCount: droppedForSection,
      totalCount: items.length,
      truncated: droppedForSection > 0,
    };
    dropped[name] = droppedForSection;
    keptCount += kept.length;
    droppedCount += droppedForSection;
  }
  dropped.total = droppedCount;

  const truncated = droppedCount > 0;
  const digest = contextPressureRecoveryDigest({
    status: "recovered",
    depth,
    maxDepth,
    maxItemsPerSection,
    sections,
    truncated,
    keptCount,
    droppedCount,
    totalCount,
  });

  return {
    status: "recovered",
    recovered: true,
    complete: false,
    digest,
    sections,
    truncated,
    keptCount,
    droppedCount,
    totalCount,
    dropped,
  };
}

export const projectContextPressureRecovery = recoverContextPressureRecovery;
export const projectWorkingContextRecovery = recoverContextPressureRecovery;
export const recoverFromWorkingContext = recoverContextPressureRecovery;

export default recoverContextPressureRecovery;

